import json,html
from pathlib import Path
import numpy as np
from prepare_foundation_report import CSS

ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'results/parametric_body'


def main():
    comparison=json.loads((OUT/'comparison.json').read_text());fits=json.loads((OUT/'wholebody_retarget.json').read_text());graph=json.loads((OUT/'model_graph.json').read_text());checks=json.loads((OUT/'scaling_verification.json').read_text())
    payload={};minimum_normal=np.inf;friction_violation=-np.inf;component_error=0.;minimum_force=np.inf
    for name,case in comparison['cases'].items():
        folder=OUT/name;fixed=np.load(folder/'fixture_data.npz');fit=np.load(folder/'retargeted_fixtures.npz');coords=case['snapshots'][0]['coordinate_names']
        for values in [fixed,fit]:
            foot=values['contact_force_N'];minimum_normal=min(minimum_normal,float(foot[:,:,2].min()))
            friction_violation=max(friction_violation,float((np.linalg.norm(foot[:,:,:2],axis=2)-.8*foot[:,:,2]).max()))
            component_error=max(component_error,float(abs(values['force_N']-values['active_force_N']-values['passive_force_N']).max()))
            minimum_force=min(minimum_force,float(values['force_N'].min()))
        payload[name]={'label':name.replace('_',' '),'height':case['stature_m'],'mass':case['mass_kg'],'segmentSize':case['subject']['segment_size'],'coordinates':coords,
                       'fixed':fixed['net_demand'].tolist(),'retargeted':fit['net_demand'].tolist(),'fixedHandSpacing':[s['hand_spacing_m'] for s in case['snapshots']],
                       'fitHandSpacing':[s['load_check']['hand_spacing_m'] for s in fits['cases'][name]],'lengths':[s['joint_center_distances_m'] for s in case['snapshots']]}
    assert minimum_normal>-1e-4 and friction_violation<1e-4 and component_error<1e-7 and minimum_force>=0
    (OUT/'force_data_audit.json').write_text(json.dumps({'status':'passed','static_configurations':len(payload)*6,'minimum_support_normal_N':minimum_normal,'maximum_circular_friction_violation_N':friction_violation,'minimum_total_muscle_force_N':minimum_force,'muscle_component_identity_max_error_N':component_error},indent=2),encoding='utf-8')
